import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"GR-RL: Going Dexterous and Precise for Long-Horizon Robotic Manipulation","description":"","frontmatter":{"title":"GR-RL: Going Dexterous and Precise for Long-Horizon Robotic Manipulation","arxiv":"2512.01801","date":"2025-12-01","authors":"Yunfei Li, Xiao Ma, Jiafeng Xu, Yu Cui, Zhongren Cui, Zhigang Han, Liqun Huang, Tao Kong, Yuxiao Liu, et al.","categories":"cs.RO, cs.LG","topics":"通用具身智能, 真实世界强化学习, VLA 后训练","outline":[2,2]},"headers":[],"relativePath":"papers/2512.01801.md","filePath":"papers/2512.01801.md","lastUpdated":null}'),l={name:"papers/2512.01801.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="gr-rl-going-dexterous-and-precise-for-long-horizon-robotic-manipulation" tabindex="-1">GR-RL: Going Dexterous and Precise for Long-Horizon Robotic Manipulation <a class="header-anchor" href="#gr-rl-going-dexterous-and-precise-for-long-horizon-robotic-manipulation" aria-label="Permalink to &quot;GR-RL: Going Dexterous and Precise for Long-Horizon Robotic Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.01801" target="_blank" rel="noreferrer">2512.01801</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-01</td></tr><tr><td><strong>作者</strong></td><td>Yunfei Li, Xiao Ma, Jiafeng Xu, Yu Cui, Zhongren Cui, Zhigang Han, Liqun Huang, Tao Kong, Yuxiao Liu, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>用离线 RL 学出的分布式 critic 当&quot;任务进度尺&quot;筛掉人类演示里的犹豫片段，再加镜像增广与潜空间噪声引导的在线 RL，把通才 VLA 特化成能自主穿鞋带的专家策略。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 的 HTML 版本是 <strong>v3</strong>（v1 提交于 2025-12-01，v3 修订于 2025-12-23），本文按 v3 全文撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要解决的问题很具体：<strong>通才 VLA 策略在需要毫米级精度、长时程、且涉及可形变物体的任务上不可靠</strong>。作者选的载体是穿鞋带——把鞋带头依次穿过多个鞋眼。这个任务同时踩中三条难点：鞋带和鞋面都是软体，接触动力学几乎无法建模；穿孔需要毫米级对位；整条流程要跨越&quot;挑对鞋带—对准鞋眼—穿过—换手接过—拉紧&quot;多个阶段，任一环出错都会级联。</p><p>重要性在于它把&quot;通用&quot;和&quot;可用&quot;之间的落差摆到了台面上。GR-3 这类模型在物体、场景、语义指令上的泛化已经相当强，但作者观察到它在上述场景直接失效，成功率只有 45.7%。如果这类失效不能被系统性修复，机器人基础模型就只能停在演示视频阶段。GR-RL 给出的答案不是换更大的模型，而是<strong>承认人类演示本身是次优的</strong>，并围绕这一点重建训练流程。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>经典做法用运动规划加预定义动作原语解鞋带类任务，能在固定构型下跑通，但换一双鞋、鞋带初始姿态不同、或中途掉落就无法恢复。把行为克隆朴素地套上去同样不行：BC 的目标是复现数据分布，而数据分布里混着操作员的迟疑与重试。</p><p>真实世界 RL 一路（如残差 off-policy 微调）确实能突破演示上界，但在长时程稀疏奖励下样本效率极低；在鞋带这种任务里，往腕部位姿或关节角上加噪声几乎撞不出一次成功，探索直接失效。世界模型一路把交互搬进想象里，但视觉预测不准会把误差搬到策略上。</p><p>与本文最接近的是同期的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9368em;vertical-align:-0.2481em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.4519em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.6</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span></span></span></span>：两者都用<strong>分布式 critic</strong> 学任务进度。差别在于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9368em;vertical-align:-0.2481em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-2.4519em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.6</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span></span></span></span> 做 advantage-conditioned denoising，而 GR-RL 直接用进度值做<strong>数据过滤</strong>再做 BC。作者的理由是这样能得到更强的离线起点，从而缩小在线探索的搜索空间。值得指出的是，&quot;稀疏终止奖励下的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 值退化成剩余步数的单调函数&quot;这一结构性观察，此前在 <a href="/notes/papers/2410.13816">V-GPS</a> 与 <a href="/notes/papers/2505.21432">Hume</a> 中已被独立利用，GR-RL 把它从&quot;测试时选动作&quot;推进到&quot;训练前筛数据&quot;。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个可复现的失败：拿 GR-3 在鞋带任务上跑 BC，成功率不到一半。第一反应通常是加数据，但作者去看了数据本身——遥操作员在穿孔时会放慢、会试探、会退回重来。这些片段在像素上和成功片段几乎一样，靠人工标注去删既昂贵又主观。</p><p>于是问题变成：<strong>能不能让模型自己判断哪一段是&quot;在往成功走&quot;</strong>。这里有一个现成的工具：如果只在回合末尾给二值奖励，那么 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 函数在成功轨迹上天然是随时间递增的，它就是一把进度尺。用离线 RL 训一个 critic，再看 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 什么时候掉下来，就等价于自动检出迟疑。</p><p>第二步来自另一个观察：部署时为了动作平滑，工程上普遍要做时序集成和 receding horizon 控制。这意味着<strong>实际执行的动作不是模型预测的动作</strong>。在粗放任务上这点错配可以忽略，在毫米级任务上不行。既然错配来自部署环节，那就必须在闭环里修——只有在线 RL 能做到。</p><p>第三步纯属工程直觉：双臂系统本身左右对称，把图像水平翻转、左右腕相机互换、动作按世界系镜像、指令里的&quot;左/右&quot;对调，就白得一份等价数据。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>人类演示里那些&quot;往回走&quot;的片段，正是让策略学坏的地方；而<strong>稀疏奖励下的 critic 值本身就是一把不需要人工标注的进度尺</strong>，进度掉下去的地方就是要删的地方。删完之后策略更干净，但仍然只见过&quot;训练时的动作&quot;，没见过&quot;部署时被平滑过的动作&quot;，所以还要让它在真实闭环里探索一次——探索不加在关节上，而是加在流模型的初始噪声上，这样采样出的动作始终落在离线学到的动作流形里。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>模型是 5B 的 Mixture-of-Transformer：一路是 VLA 策略 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（Qwen2.5-VL-3B-Instruct 作 VLM 骨干，动作 DiT 用 flow matching 训练，沿用 GR-3 只取后半段 VLM 层的 KV cache 以加速），另一路是多任务 critic <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，对每个动作 chunk 预测一串 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 值，采用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>-chunking + 分布式 RL。</p><p>以穿鞋带为例，完整流程是：</p><ol><li><strong>采集与造负样本</strong>。观测是三路 RGB + 本体感受 + 语言指令。由于遥操作数据绝大多数以成功结尾，作者标注每条演示中的&quot;重试关键帧&quot;，在 hindsight 里切出失败轨迹，让 critic 有负例可学。</li><li><strong>离线训 critic</strong>。用 TD3+BC，奖励只在回合末 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步给出，成功记 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0358em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">t</span></span></span></span></span></span></span></span></span></span></span></span>，其余为 0。critic 用分布式形式，把值域钉在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>。</li><li><strong>进度过滤</strong>。对数据集每个转移算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 内出现超过阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span> 的下跌，就把该样本判为次优并剔除。</li><li><strong>镜像增广 + BC</strong>。在过滤后的数据上做行为克隆，同时加入形态对称增广。</li><li><strong>在线潜空间引导 RL</strong>。在共享 VLM 骨干后接一个 51.5M 的噪声预测器 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，输出动作 DiT 的初始噪声；再蒸馏一个噪声空间的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ϕ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 以避免反传穿过流模型。先用离线模型跑 673 条 rollout 对齐 critic 分布并灌进 off-policy buffer，之后每收集 12 个新回合就更新 50 步，off-policy 与 on-policy buffer 各采一半。作者刻意<strong>不</strong>把遥操作数据混进 buffer，理由是那些数据的动力学与部署不匹配。</li></ol><p>真机是 ByteMini-v2：肘部执行器峰值扭矩由 17 N·m 升到 35 N·m，单臂负载 1.4 kg → 3.15 kg，底盘投影从 500×720 mm 缩到 450×650 mm。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>为什么 critic 值就是进度。</strong> 奖励定义为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3em;vertical-align:-1.25em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">{</span></span><span class="mord"><span class="mtable"><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">t</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbb">I</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span><span class="mpunct">,</span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord">0</span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span><span class="arraycolsep" style="width:1em;"></span><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.69em;"><span style="top:-3.69em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span></span></span><span style="top:-2.25em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.19em;"><span></span></span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>即只有末 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步、且整条轨迹成功时才有非零回报。在这种设定下，状态-动作值近似为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">⋅</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">t</span></span></span></span></span></span></span></span></span><span class="mord mathbb">I</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span>：成功轨迹上它随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 单调上升并趋向 1，失败轨迹上恒为 0。所以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 并不衡量&quot;这个动作有多好&quot;，它衡量的是&quot;离终止成功还有多远&quot;。这既是它能当进度尺的原因，也划定了它的能力边界（见 §9）。</p><p><strong>为什么要分布式 critic。</strong> 非分布式回归 critic 的输出无界，在长时程稀疏奖励下早期时刻监督信号极弱，会严重高估；把值建成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 上的离散分布后，输出被结构性地夹在合法区间内，作者的图 7 显示它与真实时间序更一致。这不是新理论，但在这个奖励设置下是关键工程决策。</p><p><strong>在线引导的目标。</strong> 噪声预测器最小化</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">L</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord mathbb">E</span><span class="mord"><span class="delimsizing size2">[</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ϕ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">ϵ</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2141em;vertical-align:-0.35em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">∥</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">ϵ</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord"><span class="delimsizing size2">]</span></span><span class="mord">.</span></span></span></span></span></p><p>第二项是一个 hinge：只要输出噪声的能量不超过阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 就不惩罚，超出才拉回。直觉是把探索限制在标准正态的一个球内，从而保证解码出的动作仍落在离线分布支撑上。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ϕ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 通过交叉熵蒸馏自动作空间的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，且输入噪声有 0.5 概率从标准正态采、否则从当前噪声预测器采——这一改动是为了保证噪声空间的覆盖度，原始实现没有。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：多阶段配方里每一段值多少？</strong> 作者按顺序累加组件评测。基座 GR-3 在全量遥操作数据上做 BC 得 45.7%；用学到的进度模型过滤后升到 61.6%；再加镜像增广到 72.7%；最后在线引导 RL 到 83.3%。三段各贡献约 16、11、11 个百分点，数据过滤是单项最大的一块。需要注意主结果只在图 5 中以柱状图给出，<strong>论文没有报告每个模型的评测试次数</strong>，也没有误差棒。</p><p><strong>问题二：失败发生在哪一阶段？</strong> 图 6 把成功率按&quot;拿对鞋带 → 穿进正确鞋眼 → 换手接过 → 拉紧&quot;逐级分解。数据过滤与在线 RL 主要削减穿孔环节的失败，数据增广在所有阶段都有改善但幅度较小。</p><p><strong>问题三：进度模型必须用 RL 学吗？</strong> 对照组是直接回归时间进度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>。作者报告回归版预测过度平滑，对&quot;差几毫米没插进去&quot;这类细微失败不敏感，也抓不到长期影响（例如机器人主动放下鞋带调整抓取姿态时，RL 版有明显的值跳变而回归版几乎持平）。这一对比只有曲线图，没有下游成功率数字。</p><p><strong>问题四：分布式 critic 有必要吗？</strong> 同样用 TD3+BC 训一个非分布式 critic，在一条高质量成功轨迹上其值严重高估、且与真实时间序不一致。同样只有定性曲线。</p><p>在线阶段的曲线值得单独一提：离线转在线的头几轮成功率<strong>先下降</strong>（分布偏移），随后快速回升并越过 90%；最终报告的 83.3% 取自第 500 个在线训练步的 checkpoint，而非移动平均的峰值。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：(1) 长时程高精度任务下人类遥操作数据本身次优，直接 BC 会把迟疑一起学进去。(2) 在稀疏终止奖励上做离线 RL，得到的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 值天然是任务进度，可以无标注地定位次优片段并删除。(3) 双臂系统的形态对称给出一份零成本增广，图像翻转、左右腕互换、动作镜像、指令左右对调。(4) 训练与部署的错配（时序集成、receding horizon）在毫米级任务上不可忽略，必须靠真实闭环 RL 修正。(5) 探索加在流模型的初始噪声而非关节上，配合能量 hinge 约束，能在毫米级任务上产生有效探索。</p><p><strong>3 句话版</strong>：把稀疏奖励下的 critic 当进度尺去清洗演示数据，用形态对称白拿一倍数据，再用潜空间噪声引导做真实世界在线 RL。三段累加把穿鞋带成功率从 45.7% 抬到 83.3%。核心主张是&quot;通才策略要变专家，缺的不是参数而是数据质量与部署对齐&quot;。</p><p><strong>1 句话版</strong>：用离线 RL 学出的进度函数清洗人类演示，再用潜噪声引导的在线 RL 对齐部署行为，让通才 VLA 特化成会穿鞋带的专家。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>&quot;进度值下跌&quot;等价于&quot;该片段次优、应当删除&quot;</strong>。</p><p>由 §6 的推导，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 本质是&quot;离成功还有多远&quot;的估计。因此凡是暂时远离终止状态的动作，都会被判为进度下跌——包括那些<strong>必要的恢复行为</strong>：主动把鞋带放回鞋面上重新抓靠近尖端的位置、先把鞋摆正再穿、把压在下面的那一头抽出来。这些恰恰是论文图 8 中被当作亮点展示的行为。换句话说，过滤器的判据与最终策略被称赞的能力在方向上是冲突的：前者删掉退让，后者依赖退让。</p><p>论文为这一假设提供的证据是间接的——过滤后成功率上升 16 个百分点。但这只能说明&quot;删掉一部分数据有益&quot;，不能说明&quot;删掉的正是该删的&quot;。而且从图 8 看，最终策略的恢复能力更可能来自在线 RL 阶段（那里没有过滤），而非过滤后的 BC。</p><p>还有一处方法论上的自相矛盾值得记下：§3.1 明确说人工标注次优片段&quot;可能引入更主观、更嘈杂的人类先验&quot;，因而要用学出来的进度模型；但训练该进度模型所需的失败轨迹，恰恰是靠<strong>人工标注重试关键帧</strong>在 hindsight 里造出来的。人类先验并没有被消除，只是被搬到了上游。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，全部在仿真里，不需要复现 5B 模型：</p><ul><li><strong>数据</strong>：任选一个带长时程接触的公开操作基准（如双臂插接任务），用脚本策略采 200 条成功演示，再人为注入两类噪声——(a) 随机在轨迹中插入&quot;退回 10 步再前进&quot;的迟疑段，(b) 随机抖动动作幅度。同时记录注入位置作为真值标签。</li><li><strong>实现</strong>：用一个小 CNN+MLP 的分布式 critic，按论文的稀疏终止奖励和 TD3+BC 训练；再训一个回归 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 的对照。</li><li><strong>测量</strong>：两件事。第一，把&quot;进度下跌超过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span>&quot;当作次优检测器，对着注入位置的真值算 precision/recall——这是论文完全没做、却最直接的检验。第二，比较四种 BC 数据集上的下游成功率：全量、进度过滤、回归过滤、以及<strong>直接删掉人工标注的重试片段</strong>。</li><li><strong>判据</strong>：若进度过滤对注入迟疑的 recall 高但对&quot;抖动幅度&quot;这类真实次优近乎为零，说明它只是个&quot;回退检测器&quot;；若下游成功率上&quot;进度过滤 ≈ 删人工标注片段&quot;，则学出来的进度模型没有带来超出人工标注的信息。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的替代解释是：<strong>三个阶段做的都是&quot;降低动作多模态性&quot;，而不是各自的机制在起作用</strong>。过滤删掉了偏离主模态的片段；镜像增广让每个状态都有一个对称配对，等价于对策略施加了一个平滑先验；在线 RL 的噪声预测器在 hinge 约束下趋向输出一个近乎确定的噪声，实际效果接近把随机采样退化成确定映射。三者叠加的净结果就是&quot;策略变得更确定&quot;，而毫米级任务恰恰最受益于确定性。</p><p>要证伪或证实这一点，需要一组廉价对照，论文全都没做：</p><ol><li><strong>过滤基线</strong>：只保留一次通过、无重试标注的演示（不训 critic），看能否同样到 61% 附近。</li><li><strong>增广基线</strong>：把镜像增广换成同等数据量的随机图像增强，看 72.7% 里有多少来自&quot;数据量翻倍&quot;而非&quot;对称先验&quot;。</li><li><strong>确定化基线</strong>：不做任何在线 RL，推理时把初始噪声固定为零向量或对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 个采样取均值，看能否逼近 83.3%。</li></ol><p>第三条尤其关键。如果固定噪声就能拿到接近的成绩，那么&quot;在线 RL 修正部署错配&quot;这一叙事就被&quot;采样方差是主要病因&quot;取代。论文用 Figure 5 右侧的在线曲线论证 RL 有效，但曲线的横轴是训练步数，无法排除上述解释。</p><p>另外，全部结论建立在<strong>单一任务、单一机器人、单次运行</strong>上；作者自己在 Limitations 中承认在线阶段存在行为漂移，稀疏噪声奖励下策略不稳定。这使得 83.3% 与 72.7% 之间的差距难以判断有多少是 checkpoint 选择的产物。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：GR-RL 的进度函数是&quot;到终止成功的距离&quot;，因此在结构上无法区分&quot;有害的迟疑&quot;与&quot;有益的重试&quot;。而长时程操作里恰恰是后者决定鲁棒性。作者自己在结论里也承认，把在线改进蒸馏回基座 VLA 仍是开放问题。</p><p><strong>新的 framing</strong>：不要学&quot;到成功还有多远&quot;，而要学**&quot;从这一状态出发的成功概率&quot;，并把它做成对时间不变的量**。具体地，把回合末的二值成功当作标签，训练一个<strong>可达性分类器</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord mathbf">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">Pr</span><span class="mopen">[</span><span class="mord text"><span class="mord cjk_fallback">最终成功</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord cjk_fallback">当前状态</span></span><span class="mclose">]</span></span></span></span>，而不是折扣 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>。可达性不会因为&quot;绕远路&quot;而下降——只要绕路之后仍然能成功，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 就应当保持不变。此时&quot;该删的片段&quot;被重新定义为<strong>使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 真正下降的片段</strong>（进入不可恢复区），而非仅仅使剩余步数变长的片段。这正好把有益重试与有害失误分开。</p><p><strong>可借鉴的相邻工具</strong>：安全 RL 里的可达性分析与 CBF 值函数学习已经在做同一件事（学&quot;从这里出发能否到达目标集&quot;），其学习目标是 max/min 型 Bellman 备份而非折扣求和，天然不带时间衰减；离线 RL 里的 Cal-QL 式保守校准可以缓解只用成功数据训分类器带来的乐观偏置。</p><p><strong>第一个实验</strong>：仍在鞋带或等价的长时程插接任务上，训练三个筛选器——折扣 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>（本文）、时间回归、以及无折扣可达性分类器——各自过滤同一批数据后做 BC。核心度量不是总成功率，而是<strong>在被人为打断（中途把物体拨走）后的恢复成功率</strong>。若可达性版本在总成功率相当的前提下恢复率显著更高，就说明&quot;进度&quot;与&quot;可达性&quot;确实是两个不同的量，而当前配方一直在优化错的那个。</p>',60)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
